def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_requirements = []
    urgent_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    total_agents = len(alive_opponents) + 1
    total_req = WATER_REQ
    for req in opp_requirements:
        total_req += req

    scarcity = total_req / max(1.0, supply)
    per_agent_supply = supply / max(1, total_agents)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 3
    elif hp <= 6:
        urgency += 2
    elif hp <= 8:
        urgency += 1

    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2

    if scarcity >= 2.8:
        urgency += 3
    elif scarcity >= 2.2:
        urgency += 2
    elif scarcity >= 1.7:
        urgency += 1

    if per_agent_supply < WATER_REQ * 0.55:
        urgency += 2
    elif per_agent_supply < WATER_REQ * 0.8:
        urgency += 1

    if urgent_opp >= 2:
        urgency += 1

    if supply >= 23 and hp >= 7 and no_water_days == 0:
        low_bid = DAILY_SALARY * 0.22
        if highest_prev > 0 and highest_prev < DAILY_SALARY * 0.8:
            low_bid = max(low_bid, highest_prev * 0.55)
        return float(min(budget, low_bid))

    if urgency <= 1:
        bid = max(DAILY_SALARY * 0.28, avg_prev * 0.55)
    elif urgency == 2:
        bid = max(DAILY_SALARY * 0.45, avg_prev * 0.78)
    elif urgency == 3:
        bid = max(DAILY_SALARY * 0.7, highest_prev + 2.0)
    elif urgency == 4:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 4.0)
    else:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 7.0)

    if hp >= 8 and no_water_days == 0 and supply >= 21:
        bid *= 0.88

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget)
    elif budget < DAILY_SALARY * 2.5:
        bid = min(bid, budget * 0.82)
    else:
        bid = min(bid, budget * 0.68 + DAILY_SALARY * 0.35)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, highest_prev + 6.0 if highest_prev > 0 else DAILY_SALARY * 1.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid minimally to get water
    if not alive_opponents:
        return min(my_current_budget, DAILY_SALARY * 0.2)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive'] and 'previous_trace' in opp and opp['previous_trace'] and opp['previous_trace'].get('bid') is not None:
            yesterday_bids.append(opp['previous_trace']['bid'])

    # Determine a base bid
    base_bid = DAILY_SALARY * 0.5

    # Prioritize desperation based on HP and remaining days
    if my_current_hp <= 1 or current_day == EPISODE_DAYS:
        base_bid = DAILY_SALARY * 0.95
    elif my_current_hp <= 3 or current_day >= EPISODE_DAYS - 2:
        base_bid = DAILY_SALARY * 0.8
    elif my_current_hp <= 5 or current_day >= EPISODE_DAYS - 4:
        base_bid = DAILY_SALARY * 0.65

    # Adjust based on yesterday's highest bid
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.7:
            # If desperate, try to slightly outbid more aggressively
            if my_current_hp <= 3 or current_day >= EPISODE_DAYS - 3:
                base_bid = max(base_bid, highest_prev_bid + 5)
            else:
                base_bid = max(base_bid, highest_prev_bid + 1)
        elif highest_prev_bid > base_bid: 
             base_bid = max(base_bid, highest_prev_bid + 1)

    # Consider David specifically, as he is a strong opponent from meta-round context
    if 'David' in opponents_status and opponents_status['David']['alive']:
        david_trace = opponents_status['David'].get('previous_trace', {})
        if david_trace and david_trace.get('bid') is not None:
            david_yesterday_bid = david_trace['bid']
            if david_yesterday_bid >= DAILY_SALARY * 0.7:
                base_bid = max(base_bid, david_yesterday_bid + 3) # Be slightly more aggressive against David

    # If extremely desperate (very low HP, last day), allow bidding slightly above salary
    if (my_current_hp <= 1 and current_day == EPISODE_DAYS) or \
       (my_current_hp <= 0 and current_day == EPISODE_DAYS -1):
        base_bid = base_bid * 1.05 

    final_bid = min(my_current_budget, base_bid)

    return max(0.0, final_bid)
